  "relic.torika.excavationSite": "ทะเลทรายโกบี ชั้นตะกอนยุคครีเทเชียส",
  "relic.torika.fossilRecord": "ตัวอย่างที่ฟื้นฟูมาจากซากฟอสซิลตัวอ่อนที่เก็บรักษาไว้ได้แข็งแรงเป็นพิเศษในชั้นตะกอนยุคครีเตเชียสของทะเลทรายโกบี พบข้างรังเปลือกไข่หลังพายุทรายสงบ ลายของเขาสั้นและโล่คอแทบไม่ถูกรบกวนเลย",
  "relic.torika.catalogSummary": "ตัวอย่างลูกไทรเซอราทอปส์ที่สูงพอ ๆ กับเด็กประถม",
  "relic.torika.squadNote": "ผู้ขนเสบียงและโล่แนวหน้าของโจรน้อย เธอแบกขนมกับชิ้นส่วนที่ทีมสำรวจเก็บได้ไว้บนหลังเอง และเมื่อทางถูกขวาง เธอจะก้าวออกไปก่อนใครเพื่อใช้เขาสั้น ๆ ขวางไว้",
  "relic.torika.researcherTitle": "กัปตัน",
  "relic.torika.unlockRecord": "พอถึงเวลามื้ออาหาร โทริกะจะเป็นคนแรกที่มายืนรออยู่หน้าโรงอาหารเสมอ เธอรักการกินมาก แต่พอถูกชม หน้าก็แดงไปจนถึงใบหูแล้วเอาแต่เล่นช้อน เธอขี้อายแต่ไม่ใช่คนขี้ขลาด ถ้าเรลิกตัวอื่นดูมีภัย ขาสั่นงันงกแท้ ๆ แต่กลับไปยืนอยู่ข้างหน้าเขาตั้งแต่เมื่อไรก็ไม่รู้ ทุกคนจึงมักไปหาโทริกะก่อนเสมอเมื่อมีเรื่องอันตราย และห่อขนมก็อยู่บนหลังของโทริกะเสมอ แว่นวิจัยสีเหลืองที่ฉันให้เป็นของขวัญ เธอสวมทุกวันไม่เคยขาด ได้ยินว่าเฉพาะตอนนอนเท่านั้นที่พับเก็บไว้ข้างหัวนอนอย่างเรียบร้อย เวลาอายก็มีนิสัยแกล้งดันแว่นเพื่อซ่อนหน้า คำที่เธอใช้เรียกฉันไม่เคยเปลี่ยนเลย คือ \"กัปตัน\" คงเพราะติดปากแล้ว ทุกครั้งที่เรียกจึงมีสีหน้าภูมิใจนิด ๆ",
