  "relic.luka.fossilRecord": "ตรงที่เนินทรายถล่ม โครงกระดูกที่ข้อต่อเชื่อมยาวไปถึงหางปรากฏขึ้น การเรียงของกระดูกนิ้วเท้าถูกพัฒนาเฉพาะเพื่อการวิ่งระยะสั้นที่รวดเร็ว",
  "relic.luka.catalogSummary": "ตัวอย่างที่อิงจากฟอสซิลเวโลซิแรปเตอร์โตเต็มวัย สูง 1.62 m หนัก 59 kg กล้ามเนื้อท่อนล่างพัฒนาดี และโครงเบาเหมาะกับการวิ่งเร็ว",
  "relic.luka.unlockRecord": "หลังฟื้นคืน ลูกาถูกสังเกตว่าเป็นนักวิ่งระยะสั้นที่รักบ้านและการพักผ่อนเหนือสิ่งอื่นใด ด้วยกล้ามเนื้อท่อนล่างที่แน่นสมกับนักวิ่ง เขาจึงเข้ากับเรลิกสายกินเนื้อตัวอื่นได้ดีโดยรวม แม้จะนอนเหยียดยาวพักอยู่บนโซฟาห้องวิจัย พอฉันเดินผ่านเขาก็ทักก่อนเสมอ นั่นเป็นนิสัยของเขา ระหว่างกินชีสเค้กของโปรด เขากังวลเบา ๆ ว่าถ้าอ้วนขึ้นการวิ่งอาจช้าลง แต่แล้วก็กัดอีกคำและหัวเราะว่าแค่ขยับให้เต็มที่ในการวิ่งเร็วรอบหน้าก็พอ เขาเรียกฉันว่า \"นักวิจัย\" ไม่เปลี่ยนเลย",
