  "relic.dodo.excavationSite": "มอริเชียส ชั้นเก็บรักษาในถ้ำหินปูน",
  "relic.dodo.fossilRecord": "ในชั้นเก็บรักษาที่แห้งของถ้ำหินปูน พบโครงกระดูกพร้อมเศษเปลือกไข่ ความเสียหายจากเกลือน้อย จึงกลายเป็นมาตรฐานแรกของการฟื้นคืนที่มั่นคง",
  "relic.dodo.catalogSummary": "ตัวอย่างนกที่บินไม่ได้ สูง 1.08 m หนัก 20 kg ยืนยันว่ารูปร่างเบา ปีกสั้น และจะงอยปากแข็ง",
  "relic.dodo.squadNote": "ผู้บันทึกที่อายุน้อยที่สุดของโจรน้อย เธออ้างว่าเป็นแฟนตัวยงอันดับหนึ่งของกัปตัน และเขียนชื่อนั้นไว้หน้าแรกของบันทึก",
  "relic.dodo.researcherTitle": "กัปตัน",
  "relic.dodo.unlockRecord": "โดดีเป็นเด็กที่เห็นของใหม่ทีไรก็วิ่งมาพร้อมตะโกน \"กัปตัน ดูนี่สิ!\" แม้แต่ขยะวิบวับก็ถือเป็นบันทึกการค้นพบ และใช้ปากกาขนนกจดลงบันทึกอย่างตั้งใจ แต่เวลากินข้าวของตัวเองกลับไม่จดไว้ จึงพลาดอยู่บ่อย ๆ พอจดนิสัยเล็ก ๆ น้อย ๆ ของเพื่อนและปฏิกิริยาของคนแปลกหน้า นิ้วมือเธอก็เปื้อนหมึกอยู่เสมอ บางครั้งดีใจจนก้าวเข้าไปใกล้อีกก้าว ทำให้อีกฝ่ายตกใจ แล้วตัวเองก็ตกใจถอยกลับไปเหมือนกัน ช่วงนี้เธอเงยหน้ามองดวงตาสัญญาณในหอควบคุมที่เฝ้าดูและตัดสินสัญญาณมากมายพร้อมกันอยู่นาน แล้วก็ปีนขึ้นที่สูงเพื่อตรวจการเคลื่อนไหวของเพื่อนทีละคน และพยายามเลือกเส้นทางข้างหน้าก่อนใคร แต่ตอนนี้โดดีหลงทางก่อนถนนเสียอีก บนสุดของหน้าแรกในบันทึกมีคำที่ใช้เรียกฉันว่า \"กัปตัน\" เขียนตัวใหญ่ ส่วนช่องใส่ชื่อยังว่างอยู่ คำว่าแฟนคนแรกเธอติดให้ตัวเองเอง",
