  "relic.tia.squadNote": "สมาชิกริมน้ำของโจรน้อย เธอเก็บทุกอย่างที่วิบวับและยืนกรานว่าเป็นเสบียงสำหรับกัปตัน แต่พอถูกชมจริง ๆ กลับหลบไปหลังผ้าคลุม",
  "relic.tia.researcherTitle": "นักวิจัย",
  "relic.tia.unlockRecord": "หลังฟื้นคืน เทียกระโดดลงน้ำทุกครั้งที่เห็นริมน้ำเป็นคนแรก สาดน้ำแล้ววิ่งหนี ซ้ำแล้วซ้ำเล่า พอนักวิจัยเข้าใกล้ เธอจะเอาชายผ้าคลุมบังหน้าครึ่งหนึ่งแล้วถอยหลัง แต่ทันทีที่ถูกเรียกชื่อก็วิ่งมาข้างกายและจับชายเสื้อตามไปทุกที่ ริมแม่น้ำเธอเก็บหินและเศษแก้ววิบวับเป็นกำ ๆ โดยเรียกว่าไปเก็บเสบียง แต่เศษชิ้นเล็กที่เก็บได้เป็นชิ้นแรกสุดนั้น เธอเก็บแยกไว้ในแขนเสื้อเสมอ วันที่มีคนบอกว่ามันไร้ประโยชน์ เธอปล่อยครีบหางห้อยลงและเงียบไปนาน เธอเรียกฉันว่า \"นักวิจัย\" ไม่เปลี่ยนเลย",
