  "relic.stella.excavationSite": "ชั้นตะกอนทะเลส่วนบนของชอล์กไนโอบรารา",
  "relic.stella.fossilRecord": "ในหินโคลนละเอียดของชอล์กชั้นบน พบปีกที่ยังโตไม่เต็มที่พับอยู่ เป็นช่วงก่อนที่หงอนจะก่อตัว จึงยืนยันสายพันธุ์ได้เพียงเทียบกับตัวอย่างโตเต็มวัย",
  "relic.stella.catalogSummary": "ตัวอย่างเทอโรซอร์วัยเยาว์ สูง 1.42 m หนัก 31 kg มีรูปร่างมนุษย์ หงอนที่ยังเติบโต และปีกที่พับได้กว้าง",
  "relic.stella.squadNote": "เจ้าหน้าที่สังเกตการณ์อายุน้อยที่สุดของดวงตาสัญญาณ เธออ่านเส้นทางลมล่วงหน้าเพื่อกำหนดจุดที่พันธมิตรจะบินขึ้น และเพราะยังเป็นมือใหม่จึงยังเรียกนักวิจัยว่ารุ่นพี่",
  "relic.stella.researcherTitle": "รุ่นพี่",
  "relic.stella.unlockRecord": "สเตลลาปีนขึ้นหอควบคุมและวัดทิศทางกับแรงลมใหม่หลายครั้งต่อวัน เธอสวมเสื้อคลุมวิจัยหลวมโพรกที่คลุมถึงหลังมือโดยพับแค่แขนเสื้อ และมีวิธีของเธอเองคือไม่ลบแม้แต่ตัวเลขที่ผิด แต่ปล่อยไว้ด้านในแขนเสื้ออย่างนั้น วันที่การคำนวณตรงกัน เธอส่งแค่รายงานทำเหมือนไม่มีอะไร แต่ปลายหงอนกลับตั้งชัน ตั้งแต่สัปดาห์แรกที่ถูกส่งมาประจำ เธอท่องขั้นตอนการสังเกตขั้นสูงทั้งหมดได้ ทำให้รุ่นพี่ของดวงตาสัญญาณลนลาน เมื่อเรลิกตัวน้อยที่ได้ยินเรื่องนี้มารอที่ทางเดินแล้วเดินตาม เธอบอกว่ารำคาญแต่ก็ยังเดินช้าลงให้ เธอยอมรับเองว่าสายตาชื่นชมเหล่านั้นหนักอยู่บ้าง ถ้าถามว่าเสื้อคลุมเคยเป็นของใคร เธอจะบอกว่าเป็นความลับแล้วเงียบ เธอเรียกฉันว่า \"รุ่นพี่\" ไม่เปลี่ยนเลย",
