  "relic.meron.excavationSite": "แอ่งปิสโก หินทรายแป้งทะเลชั้นล่าง",
  "relic.meron.fossilRecord": "ในหินทรายแป้งทะเลชั้นล่าง พบฟันสิบซี่ที่ยังโตไม่เต็มที่ติดอยู่กับกระดูกขากรรไกร ฟันมีหยักเลื่อยที่ยังไม่โตเต็มที่จึงขอบมน และข้างกันไม่พบบาดแผลจากการต่อสู้หรือร่องรอยการล่า พบเพียงร่องรอยการกินแมงกะพรุนและปลาตัวเล็ก ขนาดไม่ถึงครึ่งของตัวอย่างโตเต็มวัย และเป็นร่องรอยของการวนเวียนอยู่ข้างฝูงในอ่าวตื้นอันสงบ จึงถูกจัดเป็นอีกสายพันธุ์ในตอนแรก",
  "relic.meron.catalogSummary": "ตัวอย่างฉลามวัยเยาว์ สูง 1.58 m หนัก 44 kg มีรูปร่างมนุษย์ ฮู้ดครีบหลัง และหางยาว",
  "relic.meron.squadNote": "ผู้บันทึกของรูนเงียบงัน เธอวาดหน้าเรลิกทุกตัวที่ผ่านห้องดูแลแล้วติดไว้บนผนัง และจะดึงฮู้ดขึ้นทันทีที่มีคนพูดถึงภาพของเธอ",
  "relic.meron.researcherTitle": "นักวิจัย",
  "relic.meron.unlockRecord": "ความยาวคลื่นของตัวอย่างโตเต็มวัยอยู่ระดับเลวีอาธาน การฟื้นคืนจึงไม่ได้รับอนุมัติ ห้องวิจัยจึงเลือกวัยเยาว์ที่พลังยังไม่สุกงอม หลังฟื้นคืน เมรอนนั่งวาดอะไรบางอย่างทั้งวันที่มุมเย็นที่สุดของห้องดูแล ถ้าไปคุยด้วย เธอจะกอดสมุดสเก็ตช์ไว้แนบอกแล้วหลบหลังหน้าม้า แต่พอเช้าวันรุ่งขึ้น จะมีสติกเกอร์ที่วาดหน้าคนนั้นติดอยู่หน้าประตูของเขาหนึ่งแผ่น เธอแก้ภาพไม่รู้จบ ปกสมุดสเก็ตช์จึงมีตัวเลขติดไว้เสมอว่า \"ครั้งสุดท้ายจริง ๆ\" นี้เป็นครั้งที่เท่าไร แม้ในสนามรบเธอก็ไม่กล้ามองศัตรูตรง ๆ ได้แต่ลดสายตาแล้วใช้ปลายนิ้วลากตามเส้นขอบ — และศัตรูที่ถูกลากเส้นไว้จะพังทลายอย่างหนักผิดปกติภายใต้การโจมตีของเพื่อน เธอเรียกฉันว่า \"นักวิจัย\" ไม่เปลี่ยนเลย",
