  "relic.pachi.catalogSummary": "ตัวอย่างโตเต็มวัย สูง 1.55 m หนัก 47 kg มีรูปร่างมนุษย์ หางที่เคราตินหนา และกะโหลกแข็ง",
  "relic.pachi.squadNote": "มือพังประตูของเขี้ยวสัมบูรณ์ เขาใช้หัวเปิดทางที่แนวหน้าต้องการ ยืนกรานเรียกนักวิจัยว่า \"บอส\" และบ่นทุกคำสั่งแต่ก็ทำตามเสมอ",
  "relic.pachi.researcherTitle": "บอส",
  "relic.pachi.unlockRecord": "วันแรกที่ฟื้นคืน ปาจิเอาหัวชนวงกบประตูห้องดูแลจนบานพับพัง และตั้งแต่นั้นพอสวมหมวกนิรภัยให้ก็ไม่ยอมถอดเลย เขาอมลูกอมรสเชอร์รีเดินไปมาทั้งวันและทิ้งกระดาษห่อไว้ทุกที่ พอถูกทักก็กลอกตาพูดว่า \"รู้แล้วน่า\" แล้วก็เก็บจนได้ เขาบ่นทุกคำสั่งออกรบ แต่ตรงจุดที่ฉันบอกเขาไม่เคยถอยแม้ก้าวเดียว ยืนขวางหน้าจนทุกคนข้างหลังผ่านไปหมด เขาเรียกฉันว่า \"บอส\" ไม่เปลี่ยนเลย",
