  "relic.maki.fossilRecord": "จากช่องว่างในหินกรวดมน พบเขี้ยวดาบคู่ที่ยังโตไม่เต็มที่ฝังอยู่ในกระดูกขากรรไกร ขอบคมไม่มีร่องรอยการสึก จึงถูกเลือกให้ฟื้นคืน",
  "relic.maki.catalogSummary": "ตัวอย่างลูกอ่อน สูง 1.62 m หนัก 49 kg มีรูปร่างมนุษย์ หางลายจุด และเขี้ยวดาบที่โผล่ออกมา",
  "relic.maki.squadNote": "หน่วยแพทย์สนามของเฟืองรัตติกาล เขาต่อกระดูกทีมกู้ซากเข้าที่ตรงนั้นเลย เรียกเฉพาะนักวิจัยว่า \"นักวิจัย\" และตามตื๊อขอนัดตลอด",
  "relic.maki.researcherTitle": "นักวิจัย",
  "relic.maki.unlockRecord": "หลังฟื้นคืน ตัวนี้ได้รับการยกย่องว่ามีมือจัดกระดูกเก่งที่สุดในนครนิรันดร์ แค่คลำจุดที่หักครั้งเดียวก็จัดเข้าที่ทันที แล้วใช้มือเดียวกันเตรียมวัตถุดิบอาหารฟื้นฟูยกมาเสิร์ฟ เขาแต่งตั้งตัวเองเป็นแพทย์ประจำตัวของนักวิจัยและยื่นใบสมัครตรวจทุกวัน แต่ถูกปฏิเสธทุกครั้ง แล้วก็ชูหางบอกว่า \"ไม่มีตาดูของดี\" ช่องอันดับหนึ่งของตารางจัดอันดับวัตถุดิบที่ติดบนผนังห้องดูแลมีชื่อนักวิจัยเขียนอยู่ และเขายืนยันว่านั่นคือคำชมสูงสุด เขาเรียกฉันว่า \"นักวิจัย\" ไม่เปลี่ยนเลย",
