  "relic.maki.passive.desc": "เมื่อเริ่มการต่อสู้ เขาเล็งศัตรูที่มี HP ปัจจุบันต่ำสุดแล้วกระโจนเข้าหา เลือกใหม่ทันทีเมื่อกำจัดได้ ไม่เช่นนั้นเลือกใหม่ทุก 10 วินาที เมื่อได้รับความเสียหายจากศัตรูจะล่องหน 2 วินาที สูงสุด 3 ครั้งต่อการต่อสู้",
