  "relic.keris.fossilRecord": "โคลนไร้ออกซิเจนของพรุพีตรักษาเขากวางคู่ขนาดใหญ่ไว้ครบถึงโคน ด้านในมีเส้นการเจริญเติบโตซ้อนกันแน่น การวิจัยฟื้นคืนจึงเริ่มจากการนับเส้นเหล่านั้น",
  "relic.keris.catalogSummary": "ตัวอย่างเมกาโลเซรอสโตเต็มวัย สูง 1.62 m มีรูปร่างมนุษย์ เขาคู่ใหญ่โค้งเข้าด้านใน และปลายนิ้วเรียวเหมาะกับการจับกระดาษ",
  "relic.keris.squadNote": "ผู้ดูแลเอกสารของดวงตาสัญญาณ เธอไม่เคยเข้าร่วมพื้นที่แลกเปลี่ยนรายงานสังเกตการณ์ เพียงรับและจัดทำดัชนี และจดทุกอย่างที่นักวิจัยอ่านไว้ทั้งที่ไม่มีใครขอ",
  "relic.keris.researcherTitle": "รุ่นพี่",
  "relic.keris.unlockRecord": "เคริสไม่เคยออกจากห้องสมุดกลางเลยตั้งแต่ฟื้นคืน เธอแทบไม่พูดและสบตาคนได้ไม่ค่อยดี แต่กลับจำได้แม่นยำว่าใครยืมอะไรไปโดยไม่ต้องมีใครถาม โดยเฉพาะเอกสารที่นักวิจัยเคยอ่าน แม้เลยกำหนดคืนแล้วก็ไม่นำกลับเข้าชั้น แต่วางซ้อนแยกไว้ข้างโต๊ะ และถูกพบหลายครั้งว่ากำลังคัดรายชื่อนั้นลงสมุดอีกเล่ม ถามว่าชอบอะไร เธอตอบแค่ว่า นิยายรัก เธอเรียกฉันว่า \"รุ่นพี่\" ไม่เปลี่ยนเลย",
