  "relic.delopi.fossilRecord": "จากรอยแยกของหินโคลน หงอนบางคู่ปรากฏเคียงกัน กระดูกหงอนบางจนคาดว่าจะแตก แต่เนื้อเยื่อกระดูกที่ต่อกับกะโหลกยังสมบูรณ์ การวิจัยฟื้นคืนใช้เวลานานที่สุดกับการตั้งแผ่นบาง ๆ เหล่านั้นขึ้น",
  "relic.delopi.catalogSummary": "ตัวอย่างไดโลโฟซอรัสโตเต็มวัย สูง 1.45 m หนัก 41 kg มีรูปร่างมนุษย์ผอมเล็ก หงอนบางคู่ที่พับไปด้านหลังคอ และนิ้วข้อยาวเหมาะกับการเล่นไพ่",
  "relic.delopi.squadNote": "สมาชิกกู้ซากอายุน้อยที่สุดของเฟืองรัตติกาล แม้ในภารกิจแทรกซึมที่ต้องเงียบ เขาก็ไม่หยุดทำให้ของที่เก็บมาหายไปในมือแล้วกลับมาอีก รุ่นพี่จึงต้องกดหงอนของเขาลงทุกครั้ง",
  "relic.delopi.researcherTitle": "นักวิจัย",
  "relic.delopi.unlockRecord": "หลังฟื้นคืน เดโลปีถูกสังเกตว่าเป็นเด็กที่มือไวกว่าความคิด กุญแจที่หายไปจากกระเป๋าของนักวิจัยกลับมาพร้อมคำทักทายเสมอ และสีหน้าตอนคืนดูสนุกกว่าตอนหยิบไปมาก หงอนหลังคอจะกางกว้างเฉพาะตอนจะทำให้ตกใจ และดูเหมือนเขาไม่รู้ว่ามันเห็นชัดทุกอย่าง วันที่กลับจากภารกิจ เขาจะถือสำรับไพ่ไล่ตามเรลิกตัวอื่น เล่นมายากลเดิมซ้ำราวสิบครั้ง จนไม่มีใครหลงกลแล้วถึงค่อยเดินหงอยไปที่มุม เขาเรียกฉันว่า \"นักวิจัย\" ไม่เปลี่ยนเลย",
