  "relic.nodonia.excavationSite": "สหรัฐฯ รัฐแคนซัส ชอล์กสโมกีฮิลล์",
  "relic.nodonia.fossilRecord": "จากชอล์กที่ทะเลตื้นทิ้งไว้ กระดูกหงอนและรอยพิมพ์เยื่อปีกออกมาทับกัน มีรอยกระดูกหักที่หายแล้ว 12 จุด และ 9 จุดในนั้นคือร่องรอยของการบินต่อหลังกระดูกหัก",
  "relic.nodonia.catalogSummary": "ตัวอย่างเทอราโนดอนโตเต็มวัยที่ฟื้นคืนในชุดราตรีสีดำและผ้าคลุมหน้า",
  "relic.nodonia.squadNote": "ตำแหน่งแถวหน้าของห้องดูแลแห่งรูนเงียบงัน เมื่อมีตัวอย่างที่การสั่นพ้องสั่นคลอนถูกหามเข้ามา เธอจะวิ่งไปกอดก่อนใคร และปล่อยแผลของตัวเองไว้ทีหลัง",
  "relic.nodonia.researcherTitle": "เจ้าตัวน้อย",
  "relic.nodonia.unlockRecord": "โนโดเนียไม่เคยพูดว่าเจ็บ มีการบันทึกหลายครั้งว่าสีหน้าของเธอผ่อนคลายแทนที่จะตึงเครียดขณะรักษาแผลในห้องดูแล และเมื่อการรักษาจบ เธอจะลดผ้าคลุมหน้าลงด้วยท่าทีเสียดาย ตอนฝึกเธอยืนหน้าเรลิกตัวเล็กเสมอและรับการโจมตีก่อน จากนั้นก็ลูบหัวทีละคนพร้อมบอกว่า \"ทำได้ดีมาก\" ผ้าพันแผลของเธอเองไม่เปลี่ยนอยู่หลายวัน ทีมดูแลต้องตามหาตัวเธอทุกครั้ง แต่ในทางกลับกัน เมื่อคนอื่นบาดเจ็บ รอยยิ้มทุกร่องรอยจะหายไป เธอเรียกฉันว่า \"เจ้าตัวน้อย\" ไม่เปลี่ยนเลย",
