  "relic.ella.fossilRecord": "จากชั้นกรวดบนที่ราบสูง นอจมูกหนึ่งอันกับกระดูกขาหน้าออกมาพร้อมกัน เส้นการเจริญเติบโตในกระดูกหนาแน่นและมากผิดปกติ จึงถูกจัดเป็นตัวที่อายุยืนที่สุดในบรรดาตัวอย่างสายพันธุ์เดียวกัน",
  "relic.ella.catalogSummary": "ตัวอย่างสูง 1.56 m หนัก 138 kg ความหนาแน่นเกือบสามเท่าของรูปร่างมนุษย์ขนาดเดียวกันและยกไม่ขึ้น ตัวอย่างแรดขนยาวช่วงปลายวัยผู้ใหญ่นี้ถูกฟื้นคืนพร้อมยันต์ติดที่หน้าผากและแขนเสื้อ",
  "relic.ella.squadNote": "กำแพงแนวหน้าของเขี้ยวสัมบูรณ์ ขณะที่รุ่นพี่ที่ชอบโชว์แข่งกันวิ่งนำไป เธอคนเดียวยืนอยู่กับที่รักษาแนวหลังไว้ และเขียนรายงานเหตุให้คนที่พังประตู",
  "relic.ella.researcherTitle": "นักวิจัย",
  "relic.ella.unlockRecord": "ร่างกายของเอลลาแน่นหนัก แท่นวัดพังทันทีหลังฟื้นคืนจนต้องเปลี่ยนไปหนึ่งครั้ง พื้นห้องดูแลก็ต้องปูใหม่ แต่ตัวเธอเองเดินโดยไม่มีเสียง เธอใช้เวลาส่วนใหญ่ของวันในลานฝึก ทำท่าเดิมซ้ำอย่างช้ามาก ๆ และเมื่อเรลิกตัวเล็กเลียนแบบแล้วพุ่งเข้าใส่ เธอแค่หมุนข้อมือเบา ๆ วางพวกเขาลงทีละคนแล้วกลับไปท่าเริ่ม \"เด็กสมัยนี้ใจร้อนจริง\" ถูกพบว่าเธอพูดแบบนี้หลายครั้งด้วยใบหน้าอ่อนเยาว์ เธอบอกว่ายันต์ที่หน้าผากและแขนเสื้อห้ามเปียก วันฝนตกจึงเคลื่อนไหวแค่ใต้ชายคา คืนที่บานประตูพังจะได้ยินเสียงพู่กันเขียนหนังสือขอโทษ แต่คนเขียนมักไม่ใช่ฝ่ายที่ทำพัง เธอเรียกฉันว่า \"นักวิจัย\" ไม่เปลี่ยนเลย",
