  "relic.mette.unlockRecord": "ตั้งแต่ฟื้นคืน เมเทะฟังเสียงกังวานของไวโอลินนานเป็นพิเศษ เธอมีนิสัยทายางสนที่คันชักนานก่อนยกขึ้นสี ระหว่างนั้นใครพูดด้วยก็ไม่ตอบ ปกติเธอนอนกลิ้งสบาย ๆ บนพื้นห้องดูแลโดยมีคำว่า \"น่ารำคาญ\" ติดปาก แต่พอมีเรลิกที่ป่วยถูกหามเข้ามา เธอจะลุกขึ้นอย่างเงียบ ๆ แล้วไปนั่งข้าง ๆ ด้วยร่างใหญ่โตนั้น เธอสีคันชักที่เล็กแสนเล็ก พอเริ่มเล่นคำพูดก็ขาดหายไปทันทีและตามเพียงปลายคันชัก ในสนามรบเธอก็ไม่เคยสั่นคลอน ยืนข้างเพื่อนที่จังหวะเริ่มเพี้ยนเพื่อก้าวให้เข้าจังหวะ ตอนนี้เธอกำลังเตรียมเวทีที่มีไว้เพื่อฉันเพียงคนเดียว รอวันที่เสียงดนตรีของเธอจะไปถึงอย่างครบถ้วน เธอเรียกฉันว่า \"อาจารย์\" มาตลอดไม่เคยเปลี่ยน",
