  "relic.maddy.fossilRecord": "สัตว์ที่ถูกแช่แข็งซึ่งเผยออกมาเมื่อริมฝั่งน้ำแข็งพังลง ขนหนาหลอมรวมกับน้ำแข็งอยู่อย่างนั้น และการวิจัยฟื้นคืนใช้เวลานานที่สุดกับการชะลอการละลาย",
