  "relic.morphe.fossilRecord": "หินโคลนชายฝั่งกดทับไว้แม้แต่เงาของพังผืดขาหน้า กระดูกกลวง การวิจัยฟื้นคืนจึงต้องตัดสินก่อนว่าโพรงนั้นมีไว้ลดน้ำหนักหรือส่งเสียง",
  "relic.morphe.catalogSummary": "ตัวอย่างจากฟอสซิลไดมอร์โฟดอนโตเต็มวัย สูง 1.57 m หนัก 41 kg มีรูปร่างมนุษย์ พังผืดบางจากขาหน้า และจะงอยปากมีเขาสั้น",
  "relic.morphe.squadNote": "ผู้ควบคุมโดรนของดวงตาสัญญาณ เธอเป็นผู้ดูแลคนเดียวที่ลาดตระเวนทางสูงได้จบโดยไม่ต้องมีใครออกไป และหลังเธอมา การลาดตระเวนท่อระบายอากาศของหน่วยสอดแนมคนอื่นลดลงครึ่งหนึ่ง",
  "relic.morphe.researcherTitle": "ผู้ดูแล",
  "relic.morphe.unlockRecord": "มอร์เฟไม่เคยออกจากเปลของเธอ เธอทำให้เก้าอี้ที่ฝ่ายควบคุมมอบให้กลายเป็นที่ของเธอโดยสมบูรณ์ ปรับเอนจนสุด แล้วมองดู A-Dimo ที่ลอยอยู่ใกล้เพดาน เรียกแล้วเธอก็ตอบ แต่ช้าไปครึ่งจังหวะเสมอและมักสั้น ๆ ทว่าจังหวะการเคลื่อนไหวของ A-Dimo ตรงข้ามกับน้ำเสียงนั้น ผู้ควบคุมรุ่นพี่หยุดงานมาไม่รู้กี่ครั้งเพื่อดูเครื่องเดียวบินกวาดทั้งสนามรบและทิ้งเครื่องหมายไว้บนศัตรูทุกตัว เธอแทบไม่เดินไปไหน ถามว่าต้องดูตรงไหน เธอจะชี้ไปที่เพดาน และตรงนั้นก็มี A-Dimo อยู่แล้ว",
