  "relic.parua.excavationSite": "ชั้นหินทรายตอนบน หมวดหินเคิร์ตแลนด์ นิวเม็กซิโก",
  "relic.parua.fossilRecord": "ตรงที่หินทรายพังลง หงอนยาวที่ลาดไปด้านหลังเผยออกมาครบ ท่อกลวงทอดยาวไปถึงกะโหลก และเมื่อทีมฟื้นคืนเป่าลมผ่าน ก็มีเสียงกังวานต่ำคล้ายเสียงมนุษย์ออกมา",
  "relic.parua.catalogSummary": "ตัวอย่างพาราซอโรโลฟัสวัยใกล้โต สูง 1.45 m หนัก 38 kg รูปร่างมนุษย์เพรียวบาง มีหงอนกลวงลาดไปด้านหลัง และนิ้วยาวที่ไม่สั่นแม้จะน้าวสายนานแค่ไหน",
  "relic.parua.squadNote": "ดวงตาของโจรน้อย ขณะคณะสำรวจเคลื่อนเป็นกลุ่ม เธออยู่รั้งท้ายคนเดียวคอยดูทางที่มาและสิ่งที่อยู่ข้างหน้า เมื่อเห็นอะไรเธอไม่ตะโกน แต่ดึงแขนเสื้อกัปตันเบา ๆ",
  "relic.parua.researcherTitle": "กัปตัน",
  "relic.parua.unlockRecord": "พอคุยกับปารัว เธอจะถอยหลังหนึ่งก้าวก่อน ถึงอย่างนั้นสายตาเธอก็กวาดมองระยะไกลหลังคนตรงหน้าอยู่เสมอ เธอจึงรู้ก่อนใครว่าใครกำลังมา แม้เห็นอะไรก็ไม่กล้าตะโกน ได้แต่ดึงแขนเสื้อฉันเบา ๆ ซึ่งแรงกว่าที่คิด พอดึงครั้งที่สองฉันก็ถูกลากตามไปแล้ว เมื่อหยิบคันธนูขึ้น การถอยนั้นก็หายไป เธอกลั้นหายใจ เล็งอยู่นานแล้วปล่อย พอปล่อยแล้วก็ไม่แม้แต่ดูว่าโดนไหมก่อนน้าวลูกถัดไป เมื่อลมพัดผ่านหงอนกลวงที่ทอดยาวไปด้านหลัง จะเกิดเสียงต่ำคล้ายเสียงคน และทุกครั้งที่เสียงนั้นดังขึ้น เธอจะใช้สองมือกดหงอนซ่อนไว้ เวลาแบ่งขนมเธอจะเอาส่วนน้อยที่สุดไว้เอง ที่เหลือก็วางลงจานของเด็กคนอื่นโดยไม่พูดอะไร ถ้ารู้ตัวว่าฉันสังเกตเห็นแล้ว เธอจะปล่อยแขนเสื้อ ถอยหลังหนึ่งก้าว แล้วมองไปไกล ๆ อีกครั้ง",
