  "relic.shute.fossilRecord": "ในหินโคลนที่พื้นเหมือง แผ่นหลังสิบเจ็ดแผ่นยังตั้งเป็นสองแถวโดยไม่ล้ม ร่องจากหลอดเลือดพาดแน่นทั่วทุกแผ่น การวิจัยฟื้นคืนจึงต้องตัดสินก่อนว่าร่องเหล่านั้นใช้ระบายความร้อนหรือส่งสัญญาณ",
