  "relic.shute.squadNote": "คำสั่งประจำตัวของดวงตาสัญญาณ ต่างจากคนอื่นที่แบ่งกันสังเกตพื้นที่กว้าง เขาจับคนเดียวต่อหนึ่งแมตช์แล้วตามไปจนจบ ถ้าคนนั้นล้ม เขาจะไม่ส่งสัญญาณใด ๆ อีกเลยตลอดเวลาที่เหลือ",
  "relic.shute.researcherTitle": "คำสั่ง",
  "relic.shute.unlockRecord": "หลังฟื้นคืน ชูเตะไม่ขึ้นหอควบคุม เขาตั้งจอแปดจอในห้องตัวเองแล้วดูสนามรบจากตรงนั้น คุยด้วยแล้วคำตอบจะช้าไปหนึ่งจังหวะและมักสั้น แต่เมื่อเลือกคนหนึ่งได้แล้ว เขาจะพูดกับคนนั้นไม่หยุด เลี้ยวตรงนั้น เข้าไปเลย ไม่ใช่อันนั้น บอกแล้วไง ตอนนั้นแผ่นหลังของเขาจะมีสี ทิศที่แผ่นหลังสว่างขึ้นคือที่ที่คนนั้นกำลังมอง สมาชิกรอบตัวจึงเรียนทักษะเพิ่มอีกอย่าง คือการอ่านศึกจากหลังของชูเตะ ถ้าชมว่าทำได้ดี เขาจะหันไปทางจอแล้วพูดแค่ว่าก็พอใช้ เขาเรียกฉันว่า \"คำสั่ง\" มาตลอดไม่เคยเปลี่ยน",
