  "relic.dian.squadNote": "หน่วยเฝ้าระวังของโจรน้อย เธอตรวจพื้นที่อันตรายข้างหน้าพร้อมคุโระกับชิโระ และยึดทางไว้จนกว่าสมาชิกคณะสำรวจตัวน้อยจะออกไปอย่างปลอดภัย",
