  "relic.sukusuino.unlockRecord": "บันทึกภัยพิบัติ 004 ปรากฏตัวบริเวณที่ราบน้ำท่วมถึงริมแม่น้ำ สวมฮู้ดรูปปากอ้ากว้าง พันโซ่และป้ายแม่กุญแจไว้ทั่วร่าง ลากกรงเล็บโค้งและหางที่มีหนามไปด้วย มันกัดผนังด้านนอกของสิ่งก่อสร้างที่อยู่ใกล้ก่อน และบดขยี้จุดเดิมไม่หยุดจนกว่าอีกฝ่ายจะถอย ยังไม่ยืนยันว่ามาจากที่ใดและมุ่งหมายอะไร",
