  "relic.taboa.unlockRecord": "บันทึกภัยพิบัติ 005 ปรากฏตัวบริเวณพื้นที่ชุ่มน้ำเขตร้อน สวมฮู้ดรูปปากงู ลากหางยาวลายเกล็ดแดงเข้ม และห้อยโซ่กับป้ายแม่กุญแจเหมือนเครื่องประดับ มันใช้หางรัดเป้าหมายที่อยู่ใกล้ และไม่ปล่อยสิ่งที่รัดไว้จนกว่าจะล้มลง ยังไม่ยืนยันว่ามาจากที่ใดและมุ่งหมายอะไร",
