  "relic.raitia-grass.researcherTitle": "นักวิจัย",
  "relic.raitia-grass.unlockRecord": "บันทึกการระบุตัว 207 ยืนยันว่าสังกัดทำลายล้าง เป็นตัวที่ผูกเงื่อนสีเขียวในบรรดาห้าตัวที่สวมชุดนอนมีฮู้ดติดหูหนู โดดเด่นด้วยกระเป๋ารูปชีส รองเท้าแตะมีฟัน และหางลายขวางที่ปลายผูกริบบิ้น เมื่อเจออาหาร มันส่งสัญญาณด้วยเสียงฟันหน้าแทนเสียงร้อง และพี่น้องที่ได้ยินก็กรูไปที่จุดเดียวกันพร้อมกัน ตรงที่มันแทะมียอดอ่อนร่วงอยู่ และตามทางที่ผ่านไป ทุกรอยเท้ามีเมล็ดงอกจนเหลือเป็นทางสีเขียว ยังไม่ยืนยันว่าเหตุใดมันจึงไม่หยุดกินแม้ถึงฤดูจำศีล",
