  "relic.anka.fossilRecord": "พบในชั้นหินทรายที่ราบน้ำท่วมถึงริมแม่น้ำ ในท่าขดตัวโดยที่แผ่นกระดูกบนหลังแทบไม่กระจัดกระจาย กระดูกกระบองที่ปลายหางใหญ่และสึกจนกลมมน ส่วนหัวซุกอยู่ระหว่างขาหน้า จึงถูกบันทึกว่าถูกฝังขณะหลับ",
  "relic.anka.catalogSummary": "ตัวอย่างแองคิโลซอรัสวัยเยาว์ สูง 1.24 ม. หนัก 38 กก. ฟื้นฟูในร่างแบบมนุษย์ พร้อมชุดนอนติดแผ่นกระดูก หางกระบอง และกระบองที่ติดอุปกรณ์ไวท์นอยส์",
  "relic.anka.squadNote": "ผู้ดูแลเรื่องการนอนของรูนเงียบงัน เธอเปิดอุปกรณ์ไวท์นอยส์ข้างสมาชิกที่นอนไม่หลับเพื่อกล่อมให้หลับ และเฝ้าข้างเตียงสมาชิกที่ไม่สบายจนถึงที่สุด",
  "relic.anka.researcherTitle": "นักวิจัย",
  "relic.anka.unlockRecord": "หลังการฟื้นฟู อังคาใช้เวลาเกือบครึ่งวันด้วยดวงตาง่วงงุน ท้ายเสียงพูดยืดยาว หาวก่อนจะตอบเสมอ และมักถูกพบว่าหลับไปเองในห้องที่เข้าไปกล่อมสมาชิกคนอื่นให้หลับ ถ้าปลุกเธอจะกอดกระบองหนามที่ปลายหางแล้วโกรธเสียงดัง แต่มีบันทึกหลายครั้งว่าเธอขยี้ตาตื่นอยู่ข้างเตียงสมาชิกที่บาดเจ็บทั้งคืนโดยไม่ปิดอุปกรณ์เลยสักครั้ง คำที่เธอใช้เรียกฉันไม่เคยเปลี่ยนเลย คือ \"นักวิจัย\"",
