  "relic.anka.passive.desc": "ทุก 4 วินาที อุปกรณ์จะดังหนึ่งครั้ง พันธมิตรใกล้ ๆ ฟื้นฟู HP เท่ากับ 60% ของต้านทาน และศัตรูใกล้ ๆ ที่เล็งพันธมิตรที่ไม่ใช่อังคาจะได้รับความง่วงหนึ่งชั้น",
  "relic.anka.ferocity.name": "งอแงตอนง่วง",
