  "firstMeeting.anka": "อือ... นักวิจัยก็ง่วงเหรอ? นอนด้วยกันนะ... อ้าว ไม่ได้เหรอ? งั้นจะกล่อมให้หลับเอง",
  "keyword.pressure.term": "แรงดันน้ำ",
  "keyword.pressure.description": "แต่ละชั้นลดความเร็วโจมตีและความเร็วเคลื่อนที่ของศัตรูลง 8% และคงอยู่ 4 วินาที เมื่อถึงชั้นที่ 3 จะระเบิดทันที ทำให้มึนงง 2 วินาที และสร้างความเสียหายกายภาพเท่ากับ 140% ของพลังป้องกันและพลังต้านทานของผู้ใช้รวมกัน ศัตรูที่ระเบิดแล้วจะไม่สะสมชั้นอีกเป็นเวลา 6 วินาทีหลังหายมึนงง",
  "keyword.drowsy.term": "ความง่วง",
  "keyword.drowsy.description": "เมื่อสะสมครบ 3 ชั้นจะเข้าสู่[[sleep|หลับ]] 3 วินาที แต่ละชั้นคงอยู่ 6 วินาที และจะไม่สะสมขณะหลับ",
