  "relic.irna.name": "เออร์นา",
  "relic.irna.projectName": "HORIZON LINE",
  "relic.irna.origin": "อิกทิออร์นิส",
  "relic.irna.excavationSite": "พื้นตะกอนทะเลภายในตะวันตก หมวดหินชอล์กนิโอบรารา รัฐแคนซัส สหรัฐอเมริกา",
  "relic.irna.fossilRecord": "พบในชั้นหินชอล์กที่แข็งตัวหลังทะเลภายในตื้นแห้งลง มีกระดูกอกที่สันคีลชัดเจนและกระดูกปีกที่พับอยู่ ภายในจะงอยปากยังมีฟันเล็กตรงเรียงเป็นแถวเดียว การวิจัยฟื้นฟูจึงเริ่มจากยืนยันวิธีที่นกกลืนปลาตัวนี้ใช้ฟันงับเหยื่อ",
  "relic.irna.catalogSummary": "ตัวอย่างอิกทิออร์นิสวัยโตที่ฟื้นฟูขึ้นมาด้วยรูปร่างแบบมนุษย์สูง 1.56 ม. หนัก 47 กก. พร้อมผ้าคลุมปีกขาวดำ หมวกกะลาสี และปืนยาวติดกล้องเล็ง",
  "relic.irna.squadNote": "พลซุ่มยิงทางทะเลของซิกแนลอาย เมื่อมีรายงานการสังเกตส่งมา เธอจะรับเป้าหมายที่ไกลที่สุดหนึ่งเป้าและจบด้วยนัดเดียว แล้วใช้หมอกทะเลที่เกาะปากกระบอกปืนบังตัว",
  "relic.irna.researcherTitle": "คำสั่ง",
  "relic.irna.unlockRecord": "เออร์นาเลือกราวระเบียงบนดาดฟ้าหอควบคุมเป็นที่ประจำของตัวเองทันทีหลังฟื้นฟู แม้ในเมืองที่ไม่มีทะเลก็ยังชี้ไปทางที่มีเส้นขอบฟ้าได้แม่นยำ ก่อนยิงจะหายใจเข้าลึก ๆ รอจนลมเปลี่ยนทิศ และหลังยิงจะเช็ดลมที่เกาะบนลำกล้องก่อนเสมอ เธอพูดน้อย แต่ไม่เคยตกหล่นการตอบวิทยุสักครั้ง และมีการสังเกตว่าเมื่อตัดสินใจได้แล้ว เธอจะพูดทวนคำสั่งนั้นออกเสียงหนึ่งครั้งก่อนวางมือบนไกปืน คำที่เธอใช้เรียกฉันไม่เคยเปลี่ยนเลย คือ \"คำสั่ง\"",
