  "relic.ark.fossilRecord": "จากก้นหลุมทาร์พบกระดูกใบหน้าที่สั้นและสูง กับกระดูกขาหน้าที่ยาวผิดปกติ จับตัวแข็งเป็นก้อนเดียวกัน ความสูงที่เอื้อมถึงเมื่อยืนสูงเกินกว่าที่คาดไว้ตอนขุดค้นมาก การวิจัยฟื้นฟูจึงเริ่มจากการวัดว่าเมื่อตัวนี้ยืนขึ้นแล้วเงาของมันทอดไปไกลเพียงใด",
  "relic.ark.catalogSummary": "ตัวอย่างอาร์กโตดัสวัยใกล้โตที่ฟื้นฟูขึ้นมาด้วยรูปร่างแบบมนุษย์สูง 1.46 ม. หนัก 41 กก. พร้อมฮู้ดหัวหมี แขนเสื้อยาวติดกรงเล็บ และรองเท้าบูตขอบขน",
  "relic.ark.squadNote": "ผู้ป้องกันแนวหน้าของเขี้ยวสัมบูรณ์ ยืนขวางหน้าเพื่อนที่บุกเข้าไป ให้ศัตรูถอยก่อนเพื่อรักษาแนวรบ เรียกนักวิจัยว่า \"นายท่าน\" และพยักหน้าก่อนเสมอเมื่อได้รับคำสั่ง",
  "relic.ark.researcherTitle": "นายท่าน",
  "relic.ark.unlockRecord": "หลังฟื้นฟู อาร์กดึงฮู้ดลงต่ำแล้วเดินกลางทางเดินพลางหัวเราะต่ำ ๆ ว่า \"มุฮาฮา\" และเมื่อผู้ที่เดินสวนมาเบียดชิดผนังเปิดทางให้ก่อน เธอจะพอใจอยู่ในฮู้ด แต่เมื่ออยู่ต่อหน้าใบหน้าที่หวาดกลัวจริง ๆ คำพูดจะพันกันและทำอะไรไม่ถูก เฉพาะต่อหน้านักวิจัยเท่านั้นที่เธอเปิดฮู้ดไปด้านหลัง และเคยแอบยื่นห่อขนมให้ระหว่างการสังเกต คำที่เธอใช้เรียกฉันไม่เคยเปลี่ยนเลย คือ \"นายท่าน\"",
